// admin-react/src/components/GlobalModels/Filters/AgentDropdown.jsx

import { useEffect, useMemo, useState } from 'react'

import SearchableFilterDropdown from './SearchableFilterDropdown'
import { useCommonData } from '../../../context/CommonDataContext'
import {
  PERMISSIONS,
  hasPermission,
} from '../../../app/permissions'

const AgentDropdown = ({
  value = '',
  onChange,
  placeholder = 'Select Agent',
  disabled = false,
  className = '',
  label = '',
  error = '',
  required = false,

  // Selected agent name when value is not in loaded options
  fallbackLabel = '',

  // Optional Team Lead EmployeeContext ID
  teamLeadContextId = null,
}) => {
  const { activeContext, getAgents } = useCommonData()

  const [agents, setAgents] = useState([])
  const [loading, setLoading] = useState(false)
  const [fetchError, setFetchError] = useState('')

  // =========================================================
  // CHECK AGENT VIEW PERMISSION
  // =========================================================

  const canSelectAgents = hasPermission(
    PERMISSIONS.AGENTS_VIEW
  )

  // =========================================================
  // LOAD AGENTS FROM SHARED DATA PROVIDER
  // =========================================================

  useEffect(() => {
    let isMounted = true

    const loadAgents = async () => {
      if (!activeContext?.id) {
        setAgents([])
        setLoading(false)
        return
      }

      setLoading(true)
      setFetchError('')

      try {
        const data = await getAgents(teamLeadContextId)

        if (!isMounted) return

        setAgents(data)
      } catch (error) {
        if (!isMounted) return

        console.error('Failed to load agents:', error)

        setAgents([])
        setFetchError('Unable to load agents.')
      } finally {
        if (isMounted) {
          setLoading(false)
        }
      }
    }

    loadAgents()

    return () => {
      isMounted = false
    }
  }, [
    activeContext?.id,
    teamLeadContextId,
    getAgents,
  ])

  // =========================================================
  // INCLUDE CURRENT SELECTED AGENT IF NOT IN OPTIONS
  // =========================================================

  const dropdownAgents = useMemo(() => {
    if (
      value === '' ||
      value === null ||
      value === undefined ||
      !fallbackLabel
    ) {
      return agents
    }

    const exists = agents.some(
      (agent) => String(agent.id) === String(value)
    )

    if (exists) {
      return agents
    }

    return [
      {
        id: value,
        name: fallbackLabel,
      },
      ...agents,
    ]
  }, [
    agents,
    value,
    fallbackLabel,
  ])

  // =========================================================
  // HANDLE CHANGE
  // =========================================================

  const handleChange = (selectedValue, selectedOption) => {
    if (
      !canSelectAgents ||
      disabled ||
      loading
    ) {
      return
    }

    if (typeof onChange === 'function') {
      onChange(selectedValue, selectedOption)
    }
  }

  // =========================================================
  // ERROR
  // =========================================================

  const dropdownError = error || fetchError

  // =========================================================
  // RENDER
  // =========================================================

  return (
    <div className={`box-border w-full min-w-0 ${className}`}>
      {label && (
        <label
          className="
            block
            text-sm
            font-medium
            text-base-content
          "
        >
          {label}

          {required && (
            <span className="ml-1 text-error">
              *
            </span>
          )}
        </label>
      )}

      <SearchableFilterDropdown
        value={value}
        options={dropdownAgents}
        onChange={handleChange}
        includeAllOption={false}
        showLabel={false}
        searchPlaceholder="Search Agent"
        placeholder={
          loading ? 'Loading Agents...' : placeholder
        }
        disabled={
          disabled ||
          loading ||
          !canSelectAgents
        }
        className="box-border w-full min-w-0"
        getOptionValue={(option) => option.id}
        getOptionLabel={(option) => option.name}
      />

      {dropdownError && (
        <p className="mt-1 text-xs text-error">
          {dropdownError}
        </p>
      )}
    </div>
  )
}

export default AgentDropdown